import {
    RESET_REDUX,
    CREATE_MANUFACTURER_PRICE_DISCOUNT,
    CREATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS,
    CREATE_MANUFACTURER_PRICE_DISCOUNT_FAILED,
    UPDATE_MANUFACTURER_PRICE_DISCOUNT,
    UPDATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS,
    UPDATE_MANUFACTURER_PRICE_DISCOUNT_FAILED,
    GET_MANUFACTURER_PRICE_DISCOUNTS,
    GET_MANUFACTURER_PRICE_DISCOUNTS_SUCCESS,
    GET_MANUFACTURER_PRICE_DISCOUNTS_FAILED,
    GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID,
    GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_SUCCESS,
    GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_FAILED,
    SEARCH_MANUFACTURER_PRICE_DISCOUNTS,
    SEARCH_MANUFACTURER_PRICE_DISCOUNTS_SUCCESS,
    SEARCH_MANUFACTURER_PRICE_DISCOUNTS_FAILED,
} from './constants';

export const resetRedux = () => ({
    type: RESET_REDUX,
});

export const createManufacturerPriceDiscount = (priceDiscount) => ({
    type: CREATE_MANUFACTURER_PRICE_DISCOUNT,
    payload: priceDiscount,
});

export const createManufacturerPriceDiscountSuccess = (priceDiscount) => ({
    type: CREATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS,
    payload: priceDiscount,
});

export const createManufacturerPriceDiscountFailed = (message, errors) => ({
    type: CREATE_MANUFACTURER_PRICE_DISCOUNT_FAILED,
    payload: { message: message, errors: errors },
});

//Update
export const updateManufacturerPriceDiscount = (priceDiscount, id) => ({
    type: UPDATE_MANUFACTURER_PRICE_DISCOUNT,
    payload: { data: priceDiscount, id: id },
});

export const updateManufacturerPriceDiscountSuccess = (priceDiscount) => ({
    type: UPDATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS,
    payload: priceDiscount,
});

export const updateManufacturerPriceDiscountFailed = (message, errors) => ({
    type: UPDATE_MANUFACTURER_PRICE_DISCOUNT_FAILED,
    payload: { message: message, errors: errors },
});

export const getManufacturerPriceDiscounts = () => ({
    type: GET_MANUFACTURER_PRICE_DISCOUNTS,
});

export const getManufacturerPriceDiscountsSuccess = (discounts) => ({
    type: GET_MANUFACTURER_PRICE_DISCOUNTS_SUCCESS,
    payload: discounts,
});

export const getManufacturerPriceDiscountsFailed = (message, errors) => ({
    type: GET_MANUFACTURER_PRICE_DISCOUNTS_FAILED,
    payload: { message: message, errors: errors },
});

//Get wholesaler price discount by id

export const getManufacturerPriceDiscountById = (id) => ({
    type: GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID,
    payload: id,
});
export const getManufacturerPriceDiscountByIdSuccess = (item) => ({
    type: GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_SUCCESS,
    payload: item,
});

export const getManufacturerPriceDiscountByIdFailed = (message, errors) => ({
    type: GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_FAILED,
    payload: { message: message, errors: errors },
});

//Search

export const searchManufacturerPriceDiscounts = (query) => ({
    type: SEARCH_MANUFACTURER_PRICE_DISCOUNTS,
    payload: query,
});
export const ssearchManufacturerPriceDiscountsSuccess = (variations) => ({
    type: SEARCH_MANUFACTURER_PRICE_DISCOUNTS_SUCCESS,
    payload: variations,
});

export const searchManufacturerPriceDiscountsFailed = (message, errors) => ({
    type: SEARCH_MANUFACTURER_PRICE_DISCOUNTS_FAILED,
    payload: { message: message, errors: errors },
});
